// pages/Feed.jsx
import React, { useEffect, useState, useRef } from 'react';
import { useNavigate } from 'react-router-dom';
import ReviewCard from '../components/ReviewCard';
import { fetchReviews } from '../api/reviewApi';

// Feed: updated UI — hero banner, prominent roulette CTA, composer and 3-column grid

  const sampleReviews = [
  // 스킨케어
  {
    _id: 'r001', author: { username: '수아' }, title: '피부가 환해지는 비타민C 세럼', text: '싸걀!!!! 2주 썼는데 피부톤 ㅈㄴㅈㄴ 밝아졌어ㅜㅜ 흡수력 미쳤고 끈적임 1도 없음 ㄹㅇ 촉촉해서 아침에 바르면 화장이 겁나 잘먹어요ㅜ 완전 인생세럼 등극이야 여러분들도 꼭 사서 써보셈!! 알러빗ㅜㅜ', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 24, likes: 456, comments: 38, tags: ['세럼', '미백', '비타민C'], category: 'skincare', rating: 4.8
  },
  { _id: 'r002', author: { username: '민지' }, title: '촉촉함 미친 수분크림 추천', text: '건성인 나한테 인생템 찾음 아침까지 촉촉해서 감동받앗어 ㄹㅇㅜ향도 은은하고 가성비까지 개개개객미쳣🤑😍👍 용량 넉넉해서 맘껏 덕지덕지 발라도 되고 진짜 이뻐용가리ㅜ 건성분들 이거 무조건 사세용!!', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 48, likes: 289, comments: 22, tags: ['수분크림', '보습', '건성피부'], category: 'skincare', rating: 4.5 },
  { _id: 'r004', author: { username: '지우' }, title: '블랙헤드 싹 정리해주는 클렌징', text: '매일 쓰니까 모공이 점점 깨끗해지는게 느껴져 거품도 뽀송뽀송하고 세안 후에도 안땅겨서 너무 조아용ㅜ✌️😊😋 모공고민 잇으면 이거 무조건 사야해!! 진짜 갓템이야 알러빗ㅜㅜ', images: ['/images/클렌징폼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 5, likes: 367, comments: 29, tags: ['클렌징', '모공케어', '블랙헤드'], category: 'skincare', rating: 4.6 },
  { _id: 'r006', author: { username: '서연' }, title: '진정 갓팩 찾음', text: '피부 예민할때 이거 붙이면 바로 차분해져 진정효과 실화냐구 매일 써도 가격 부담없어서 개좋음 민감피부분들 이거 강추드림!! 여러분들도 꼭 사서 쓰면 좋겟슨! 알러빗이야ㅜㅜ', images: ['/images/마스크팩리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 200, likes: 198, comments: 16, tags: ['마스크팩', '진정', '민감피부'], category: 'skincare', rating: 4.4 },
  { _id: 'r007', author: { username: '예린' }, title: '레티놀 입문 이걸로 시작함', text: '레티놀 처음 쓰는데 자극 하나도 없고 피부결이 진짜 달라짐ㅜㅜ 모공도 줄어드는 느낌이고 아침에 세안하면 꿀피부됨 ㄹㅇ 초보자분들 이거로 입문하세요!! 순해서 매일 써도 됨👍', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 30, likes: 342, comments: 28, tags: ['레티놀', '안티에이징', '피부결'], category: 'skincare', rating: 4.7 },
  { _id: 'r008', author: { username: '소민' }, title: '토너패드 개꿀템 발견', text: '아침에 이거로 닦아내면 피부 정리 끝!! 각질도 정리되고 보습도 되고 일석이조야ㅋㅋ 귀찮을때 세안대신 이거로 대체해도 됨 여행갈때도 필수템이야 강추강추!!🥰', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 55, likes: 278, comments: 19, tags: ['토너패드', '각질케어', '간편케어'], category: 'skincare', rating: 4.5 },
  
  // 메이크업
  { _id: 'r003', author: { username: '윤서' }, title: '커버력 갑 쿠션 발견했어요', text: '얇게 발리는데 커버력 실화냐고 (⸝⸝ʚ̴̶̷̆ ̯ʚ̴̶̷̆⸝⸝) 무너짐도 없고❌🙅‍♀️❌ 자연광 아래서 ㅈㄴ 예뻐요 광채 미침ㅋㅋㅋ 여름에도 버틸듯!! 데일리 쿠션 찾는분들 이거 강추드려용 진짜 이거 없으면 어캄ㅜ', images: ['/images/파운데이션리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 72, likes: 523, comments: 45, tags: ['쿠션', '베이스', '커버력'], category: 'makeup', rating: 4.7 },
  { _id: 'r005', author: { username: '하은' }, title: '발색 미친 틴트 찾았다', text: '헐 색상 너무 이뻐서 뒤집어짐 발색도 미치고 지속력도 미침 ㄹㅇ❤️🚨  입술 안건조해서 데일리로 딱이야(۶•̀ᴗ•́)۶ !! 립덕후들 이거 찐이야 제발 사세요ㅜ 안사면 손해임 ㅈㄴ 이뻐용가리!!', images: ['/images/립스틱리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 120, likes: 612, comments: 51, tags: ['립스틱', '틴트', '립메이크업'], category: 'makeup', rating: 4.9 },
  { _id: 'r009', author: { username: '유나' }, title: '아이섀도우 팔레트 대박', text: '색조합 미쳤고 발색 찢었어ㅜㅜ 가루날림 없고 블렌딩도 너무 잘돼!! 이거 하나면 데일리부터 파티룩까지 다 가능함 진짜 갓팔레트야💖 색 다 예뻐서 뭐 바를지 고민됨ㅋㅋ', images: ['/images/립스틱리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 80, likes: 445, comments: 37, tags: ['아이섀도우', '팔레트', '아이메이크업'], category: 'makeup', rating: 4.8 },
  { _id: 'r010', author: { username: '채원' }, title: '마스카라 진짜 안번져', text: '속눈썹 올리고 이거 바르면 하루종일 컬 유지됨!! 판다눈 절대 안되고 클렌징도 잘돼 ㅠㅠ 진짜 찾았다 인생마스카라ㅜ 롱래쉬 효과도 있어서 속눈썹 짧은 분들 강추!!👀✨', images: ['/images/파운데이션리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 95, likes: 389, comments: 31, tags: ['마스카라', '아이메이크업', '컬지속'], category: 'makeup', rating: 4.6 },
  { _id: 'r011', author: { username: '다현' }, title: '블러셔 이거 개예뻐', text: '자연스럽게 홍조 올라온거같은 색감이야ㅜㅜ 브러시로 살살 올리면 복숭아처럼 예쁨!! 과하지않고 은은해서 데일리로 딱이야 색 다 모으고싶음ㅋㅋㅋ 존예💕', images: ['/images/립스틱리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 110, likes: 312, comments: 24, tags: ['블러셔', '치크', '메이크업'], category: 'makeup', rating: 4.7 },

  // 바디케어
  { _id: 'r012', author: { username: '지민' }, title: '바디로션 향기 미침', text: '바르고 나면 은은하게 향 남아있어서 향수 필요없음ㅜㅜ 보습력도 좋고 끈적임 없이 흡수 빨라!! 샤워 후에 바르면 촉촉함이 아침까지 유지됨 향덕후들 이거 사세요!!🌸', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 40, likes: 267, comments: 21, tags: ['바디로션', '보습', '향기'], category: 'bodycare', rating: 4.5 },
  { _id: 'r013', author: { username: '은지' }, title: '각질제거 스크럽 찐템', text: '일주일에 2번 쓰는데 피부가 진짜 매끈해짐!! 팔꿈치 무릎 각질 싹 정리되고 바디로션 흡수도 더 잘돼 ㅎㅎ 바디관리 시작하는분들 이거부터 사세요 필수템임✨', images: ['/images/마스크팩리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 65, likes: 198, comments: 15, tags: ['스크럽', '각질케어', '바디케어'], category: 'bodycare', rating: 4.4 },
  { _id: 'r014', author: { username: '나연' }, title: '핸드크림 존좋', text: '손 건조할때 바르면 바로 촉촉해짐!! 향도 은은하고 끈적임 없어서 바로 일해도 됨ㅋㅋ 미니사이즈라 파우치에 쏙 들어가서 휴대하기도 좋아 손 자주 씻는분들 필수!!🙌', images: ['/images/cream.png'], createdAt: Date.now() - 1000 * 60 * 60 * 150, likes: 234, comments: 18, tags: ['핸드크림', '보습', '휴대용'], category: 'bodycare', rating: 4.6 },
  { _id: 'r015', author: { username: '수빈' }, title: '바디미스트 향 찢었다', text: '뿌리면 기분 좋아지는 향이야ㅜㅜ 무겁지않고 가벼워서 데일리로 뿌리기 좋음!! 향 지속력도 괜찮고 여러겹 뿌려도 안부담스러워 향수 대신 이거 쓰는중💜', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 180, likes: 289, comments: 22, tags: ['바디미스트', '향기', '데일리'], category: 'bodycare', rating: 4.5 },

  // 패션
  { _id: 'r016', author: { username: '현아' }, title: '가을 니트 찾았다', text: '촉감 부드럽고 따뜻해ㅜㅜ 색상도 예쁘고 핏도 너무 좋아!! 이너로 입어도 되고 단독으로 입어도 예쁨 가성비 미쳤고 컬러별로 다 사고싶음ㅋㅋㅋ 완전 강추야💕', images: ['/images/커뮤니티3.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 35, likes: 356, comments: 29, tags: ['니트', '가을패션', 'OOTD'], category: 'fashion', rating: 4.7 },
  { _id: 'r017', author: { username: '혜진' }, title: '청바지 핏 미쳤어', text: '다리 길어보이고 엉덩이 예쁘게 잡아줘ㅜㅜ 신축성도 있어서 편하고 세탁해도 안늘어남!! 데일리로 매일 입을듯 ㅋㅋ 청바지 찾는분들 이거 사세요 핏 보장함👖✨', images: ['/images/커뮤니티1.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 90, likes: 423, comments: 35, tags: ['청바지', '데님', '데일리룩'], category: 'fashion', rating: 4.8 },
  { _id: 'r018', author: { username: '지효' }, title: '가방 너무 예뻐서 울었다', text: '디자인 미니멀한데 고급져보여ㅜㅜ 수납력도 좋고 가벼워서 매일 들고다님!! 어디에 매치해도 다 잘어울려 ㅎㅎ 인생가방 찾음 색깔별로 다 사고싶다💼', images: ['/images/커뮤니티2.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 130, likes: 378, comments: 28, tags: ['가방', '미니백', '데일리백'], category: 'fashion', rating: 4.6 },
  { _id: 'r019', author: { username: '소연' }, title: '코트 가성비 미쳤다', text: '이 가격에 이 퀄리티 실화냐고ㅜㅜ 따뜻하고 핏도 예쁘고 색상도 고급스러워!! 겨울 아우터 고민이면 이거 무조건 사세요 후회안함 보장함!!🧥❄️', images: ['/images/커뮤니티3.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 170, likes: 445, comments: 38, tags: ['코트', '겨울패션', '아우터'], category: 'fashion', rating: 4.9 },

  // 라이프스타일
  { _id: 'r020', author: { username: '채연' }, title: '디퓨저 향 대박', text: '방에 놔두니까 집 전체가 호텔같은 향이야ㅜㅜ 은은하게 퍼져서 부담없고 지속력도 좋아!! 친구들 올때마다 어디꺼냐고 물어봄ㅋㅋ 집꾸미기 시작하면 이거부터 사세요🏠✨', images: ['/images/마스크팩리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 45, likes: 312, comments: 25, tags: ['디퓨저', '홈프래그런스', '인테리어'], category: 'lifestyle', rating: 4.7 },
  { _id: 'r021', author: { username: '유진' }, title: '캔들 분위기 최고', text: '불 켜놓으면 방 분위기가 달라져ㅜㅜ 향도 좋고 연소시간도 길어서 가성비 좋음!! 자기전에 켜놓고 힐링하는중 ㅎㅎ 스트레스 받을때 이거 켜면 마음이 편해져🕯️💕', images: ['/images/비타민세럼리뷰.jpg'], createdAt: Date.now() - 1000 * 60 * 60 * 100, likes: 267, comments: 19, tags: ['캔들', '힐링', '홈카페'], category: 'lifestyle', rating: 4.6 },
